from __future__ import absolute_import
from taf.ul.oam.selenium_rap_manager.common import TabBar, LocalBasicPage
from selenium.common.exceptions import TimeoutException


class RAP(LocalBasicPage):
    SOFTWARE_INFO_XPATH = '//h4[text()="Software information"]/following-sibling::table/tbody//td[text()="{}"]/following-sibling::td[last()]'

    def __init__(self, driver):
        super(RAP, self).__init__(driver)
        self._tab_bar = TabBar(driver)
        self._tab_bar.click_rap()

    def get_software_infomation(self):
        info_map = {'active_package': 'Active package:',
                    'passive_package': 'Passive package:',
                    'running_package': 'Running package:',
                    'active_sw_version': 'Active SW version:',
                    'passive_sw_version': 'Passive SW version:'
                    }
        ret = {}
        for key, text in info_map.items():
            try:
                value = self.get_text_by_xpath_until_element_visible(self.SOFTWARE_INFO_XPATH.format(text))
            except TimeoutException:
                value = ''
            ret[key] = value
        return ret
